from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    marker = next((v for v, n in counts.most_common() if v != background), None)
    out = [row[:] for row in grid]
    if marker is None:
        return out
    for r in range(h):
        positions = [c for c, value in enumerate(grid[r]) if value == marker]
        for left, right in zip(positions, positions[1:]):
            for c in range(left + 1, right):
                out[r][c] = 3
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        for top, bottom in zip(positions, positions[1:]):
            for r in range(top + 1, bottom):
                out[r][c] = 3
    return out
